using System.Text;

namespace Alidade.OsmGen.Generators;

/// <summary>
///   Shared utilities for emitting C# source text from generator output.
/// </summary>
internal static class CodeGenHelper
{
    /// <summary>
    ///   The standard auto-generated file header placed at the top of every generated file.
    /// </summary>
    public const string AutoGeneratedHeader = """
        // <auto-generated>
        //   This file was generated by Alidade.OsmGen. Do not edit manually.
        //   Run `dotnet run --project Alidade.OsmGen` to regenerate.
        // </auto-generated>
        #nullable enable
        #pragma warning disable CS1591 // Missing XML comment for publicly visible type or member
        """;

    /// <summary>
    ///   Escapes a string for use as a C# verbatim string literal value (i.e. inside <c>@"..."</c>).
    ///   Only double-quotes need escaping in verbatim literals.
    /// </summary>
    public static string EscapeVerbatim(string? s)
        => (s ?? "").Replace("\"", "\"\"");

    /// <summary>
    ///   Emits a C# string literal. Uses <c>null</c> when <paramref name="s"/> is null.
    /// </summary>
    public static string StringLiteral(string? s)
        => s is null ? "null" : $"@\"{EscapeVerbatim(s)}\"";

    /// <summary>
    ///   Emits a C# <c>bool</c> literal.
    /// </summary>
    public static string BoolLiteral(bool b)
        => b ? "true" : "false";

    /// <summary>
    ///   Emits a C# <c>double?</c> literal, or <c>null</c>.
    /// </summary>
    public static string NullableDoubleLiteral(double? d)
        => d is null ? "null" : d.Value.ToString("G17", System.Globalization.CultureInfo.InvariantCulture);

    /// <summary>
    ///   Emits a C# inline array initializer for a list of strings, e.g. <c>["a", "b"]</c>.
    /// </summary>
    public static string StringArray(IEnumerable<string> items)
    {
        string[] arr = [.. items];

        if (arr.Length == 0)
        {
            return "[]";
        }

        return "[" + string.Join(", ", arr.Select(StringLiteral)) + "]";
    }

    /// <summary>
    ///   Emits a C# <c>Dictionary&lt;string, string&gt;</c> initializer.
    /// </summary>
    public static string StringDictionary(IEnumerable<KeyValuePair<string, string>> pairs)
    {
        KeyValuePair<string, string>[] arr = [.. pairs];
        if (arr.Length == 0)
        {
            return "new Dictionary<string, string>()";
        }

        StringBuilder sb = new("new Dictionary<string, string> { ");
        foreach (KeyValuePair<string, string> kv in arr)
        {
            sb.Append($"[{StringLiteral(kv.Key)}] = {StringLiteral(kv.Value)}, ");
        }
        sb.Append('}');

        return sb.ToString();
    }

    /// <summary>
    ///   Writes a file, creating parent directories as needed, and logs the path.
    /// </summary>
    public static void WriteFile(string path, string content)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, content, Encoding.UTF8);

        Console.WriteLine($"  wrote {Path.GetRelativePath(Directory.GetCurrentDirectory(), path)} ({content.Length:N0} chars)");
    }
}
